<template>
    <section>
        <tg-list :listType="['List']" ModuleName="Asset" SubModuleCode="Asset" :IsShowAction="isShowAction"
            :showCheckBox="true" :PageSize="PageSize" IdentityColumn="AssetRequisitionId"
            :HeaderText="$t('PurchaseRequestApproval')" :ListData="ProductData" :HeaderData="Headers" :widgets="widgets"
            :callbackfunction="FetchData" :HeaderButtons="listheaderbuttons" :TotalRecords="TotalRecord"
            :SearchFields="leftSearchFields" :RenderRowActionMethod="renderActions"
            :ListDataCallBackFunction="FetchData" :LegendArray="LegendArray" :SortExp="SortExp"
            :NorecordfoundText="$t('NoRecordfound')" :SortBy="SortBy" v-on:LeftsearchButtonClick="leftCommonSearch"
            v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick"
            v-on:ActionButtonClick="actionButtonClick" v-on:SortdataButtonClick="sortdata">


            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME == 'CreatedAt'">
                    <span :title="$options.filters.formatDateTime(data.row.CreatedAt)">{{
                        $options.filters.formatDateTime(data.row.CreatedAt) }}</span>
                </template>

                <template v-if="data.column.COLUMN_NAME == 'StatusName'">
                    <span v-if="data.row.status_code == 'NEW_ASSET_REQUISITION_APPROVED'" :title="$t('Approved')"
                        class="px-2 bg-primary text-center text-white d-block">
                        {{ $t('Approved') }}
                    </span>
                    <span v-else-if="data.row.status_code == 'NEW_ASSET_REQUISITION_REJECTED'" :title="$t('Rejected')"
                        class="px-2 bg-danger text-center text-white d-block">
                        {{ $t('Rejected') }}
                    </span>
                    <span v-else-if="data.row.status_code == 'ACT'" :title="$t('Active')"
                        class="px-2 bg-success text-center text-white d-block">
                        {{ $t('Active') }}
                    </span>

                </template>


            </template>
        </tg-list>
        <Compare v-if=isCompare @ClosePOPuP="ClosePOPuP" :AssetRequisitionId="AssetRequisitionId"
            :RequisitionData="RequisitionData">
        </Compare>
    </section>
</template>

<script>
import Schema from "../PurchaseOrder/NewProductRequestSchema"
import DataService from '../../service/DataService'
// import RequisitionViewModel from '../../components/Modal/NewRequisitionViewModel.vue'
import Compare from "./Compare.vue"
export default {
    components: {

        Compare
    },
    data() {
        return {
            listheaderbuttons: Schema.buttons,
            leftSearchFields: Schema.leftsearchSchema,
            listActions: [
                // {
                //     title: 'Edit',
                //     callbackfunction: 'Edit',
                //     href: 'javascript:void(0)',
                //     icon: 'fa fa-pencil action-icon',
                //     isVisible: false,
                //     isDisabled: false,
                //     additionalSpan: ''
                // },
                {
                    title: 'View',
                    callbackfunction: 'View',
                    href: 'javascript:void(0)',
                    icon: 'fa fa-eye  action-icon',
                    isVisible: false,
                    isDisabled: false,
                    additionalSpan: '',

                },
                {
                    title: 'Approve/Reject',
                    callbackfunction: 'openApproveReject',
                    href: 'javascript:void(0)',
                    icon: 'fa fa-reply  text-info action-icon',
                    isVisible: true,
                    isDisabled: false,
                    additionalSpan: ''
                },

            ],
            LegendArray: [],
            ProductData: [],
            PageSize: 10,
            PageNumber: 1,
            PageSizeOption: null,
            StatusListForListing: [],
            Headers: [{
                "COLUMN_NAME": "ProductName",
                "DATA_TYPE": "image",
                "SORTABLE": true,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('ProductName'),
                "DISPLAY_ORDER": 1,
                settings: {
                    clickEvent: this.clickEventOfColumn,
                    formatter: this.columnDataFormatter,
                }
            },
            {
                "COLUMN_NAME": "AssetType",
                "DATA_TYPE": "text",
                "SORTABLE": true,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('ProductType'),
                "DISPLAY_ORDER": 2
            },
            {
                "COLUMN_NAME": "Quantity",
                "DATA_TYPE": "text",
                "SORTABLE": true,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('RequestedQuantity'),
                "DISPLAY_ORDER": 3
            },
            {
                "COLUMN_NAME": "StatusName",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": "Status",
                "DISPLAY_ORDER": 10,
                settings: {
                    isInSlot: true
                }

            },
            {
                "COLUMN_NAME": "Description",
                "DATA_TYPE": "text",
                "SORTABLE": true,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('Reason'),
                "DISPLAY_ORDER": 4,
            },
            {
                "COLUMN_NAME": "CreatedBy",
                "DATA_TYPE": "text",
                "SORTABLE": true,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('CreatedBy'),
                "DISPLAY_ORDER": 5,

            },
            {
                "COLUMN_NAME": "CreatedAt",
                "DATA_TYPE": "Date",
                "SORTABLE": true,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('CreatedAt'),
                "DISPLAY_ORDER": 6,
                settings: {
                    isInSlot: true
                }
            },
            ],
            noRecord: true,
            TotalRecord: 0,
            CurrentPage: 1,
            TotalPages: 0,
            SortBy: '',
            SortExp: '',
            isPaged: 1,
            searchCondition: "",
            widgets: [

            ],
            isShowAction: true,
            isCompare: false,
            RequisitionData: []
        }
    },
    async created() {
        var vm = this;
        vm.GetPrivilege();
        await vm.GetPageSize();
        Schema.bindleftCommonSearchdropdown(vm, 'AssetRequisition', 'Product Type');
        vm.FetchData();
        vm.listheaderbuttons[0].isvisible = false;

    },

    methods: {
        columnDataFormatter: function (row, column) {
            return row[column.COLUMN_NAME];
        },
        async GetPageSize() {
            var vm = this;
            var params = 'key=DefaultPageSize'
            await DataService.GetConfigurationValueForCompanyByKey(params).then((response) => {
                if (response.data != null) {
                    vm.PageSize = parseInt(response.data);
                }
            });
        },
        ClosePOPuP() {
            var vm = this;
            vm.isCompare = false;
        },

        GetPrivilege() {

            var paramEdit = 'controller=AssetRequisition&action=EditPurchaseRequest';
            var paramApproveReject = 'controller=AssetRequisition&action=PurchaseRequestApproveReject';

            // Check privilege for EditPurchaseRequest
            DataService.CheckPrivilege(paramEdit).then(function (response) {
                if (response.data) {
                    // User has privilege, do nothing or add logic here
                } else {
                    this.listActions[0].isVisible = false;
                }
            });

            // Check privilege for PurchaseRequestApproveReject
            DataService.CheckPrivilege(paramApproveReject).then(function (response) {
                if (response.data) {
                    // User has privilege, do nothing or add logic here
                } else {
                    this.listActions[2].isVisible = false;
                }
            });
        },

        async FetchData() {
            var vm = this;
            vm.isLoading = true;
            var params = `pageSize=${vm.PageSize}&pageNumber=${vm.PageNumber}&sortBy=${vm.SortBy}&sortExp=${this.SortExp}&${vm.searchCondition}`;
            DataService.PurchaseApprovalListing(params).then(response => {
                if (response.data != null) {
                    let responseData = JSON.parse(response.data.result).data
                    if (responseData.length > 0) {
                        responseData.forEach(ele => {
                            if (ele.status_code == 'NEW_ASSET_REQUISITION_APPROVED') {
                                ele.isCheckBoxDisabled = true;
                            }
                        });
                        vm.ProductData = responseData;
                        vm.TotalRecord = responseData[0].TOTAL;
                        vm.TotalPage = Math.ceil(vm.TotalRecord / vm.PageSize);
                        vm.CurrentPage = vm.PageNumber;
                        vm.noRecord = false;
                        vm.isLoading = false;
                        vm.listheaderbuttons[1].isdisabled = true;

                    }
                    else {
                        vm.noRecord = true;
                        vm.ProductData = [];
                        vm.TotalRecord = 0
                        vm.isLoading = false;
                    }
                }

            });
        },
        // clickEventOfColumn: function (row, column) {
        //     this.$router.push({
        //         name: 'ViewProductRequest',
        //         params: { id: row.AssetRequisitionId }
        //     });
        // },
        clickEventOfColumn: function (row, column) {
            this.$router.push({
                name: 'ViewProductRequest',
                params: {
                    id: row.AssetRequisitionId,
                    status: row.status_code   // 👈 added parameter
                }
            });
        },
        leftCommonSearch: function (value) {
            this.PageNumber = value.PageNumber;
            this.isPaged = 1;
            if (typeof value.searchCondition != 'undefined') {
                this.searchCondition = value.searchConditionJson;
            }
            else {
                this.searchCondition = "";
            }
            this.FetchData();
        },
        currentPageMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchData();
        },
        GetPageSizeOption: function () {
            var list = [];
            var defaultPageSize = 10;
            for (var i = defaultPageSize; i < defaultPageSize + 95; i += 5) {
                list.push(i);
            }
            this.PageSizeOption = list;
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchData();
        },
        commonHeaderButtonClick(event) {
            switch (event.callbackfunction) {
                case "RequestNewProductType":
                    this.RequestNewProductType();
                    break;
                case "deleteItem":
                    this.deleteItem();
                    break

            }
        },

        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }

            this.FetchData();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        actionButtonClick: function (callbackfunction, item) {
            var vm = this;
            switch (callbackfunction) {
                case "Edit":
                    vm.EditRequestDetails(item)
                    break;
                case "openApproveReject":
                    vm.openApproveReject(item);
                    break;
            }
        },
        EditRequestDetails(item) {
            this.$router.push({ name: "AddNewRequisition", params: { reqForm: 'ProductTypeList', items: item } });
        },
        openApproveReject(item) {
            var vm = this;
            vm.isCompare = true;
            vm.AssetRequisitionId = item.AssetRequisitionId
        },
        renderActions(row) {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'Edit':
                        if (row.status_code == "NEW_ASSET_REQUISITION_APPROVED") {
                            action.isDisabled = true;
                        }
                        else {
                            action.isVisible = true;
                        }
                        break;
                    case 'Approve/Reject':
                        action.isVisible = true;
                        break;
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        deleteItem() {
            var vm = this;
            var val = "";
            $('.chkItems:checkbox:checked').not("[id^='chkAll']").each(function () {
                if (val.length > 0)
                    val += ',';
                val += $(this).val();
            });

            if (val.length > 0) {
                vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("New_Requisition")), function () {
                    var postJSON = {
                        ids: val,
                        tblname: "TALYGEN_new_asset_requisition",
                        primarycolname: "asset_requisition_id"
                    };
                    vm.isLoading = true;
                    var poststing = JSON.stringify(postJSON);
                    DataService.NewAssetRequisitionDelete(poststing).then(response => {
                        if (response.data) {
                            vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('New_Requisition')]), "Success", true, vm.$t('Alert'));
                            vm.FetchData();
                        }
                        else {
                            vm.ShowAlert(vm.$t('DeletedError', [vm.$t('New_Requisition')]), "failure", true, vm.$t('Alert'));
                        }
                    });
                });
            }

        },
        RequestNewProductType() {
            this.$router.push({ path: '/AssetRequisition/AddNewRequisition' })
        },
        viewRequest(item) {
            var vm = this;
            vm.isCompare = true;
            vm.RequisitionData = item;

        },
        viewRequestPurchase(item) {
            var vm = this;
            vm.IscheckApprovePurchaseData = true;
            vm.RequisitionData = item;

        },
        ClosePOP: function () {
            var vm = this;
            vm.IscheckApprovePurchaseData = false;
        },

    },

}

</script>